// static
bool UnionTraits<::network::mojom::DeviceBoundSessionEventTypeDetails::DataView, ::network::mojom::DeviceBoundSessionEventTypeDetailsPtr>::Read(
    ::network::mojom::DeviceBoundSessionEventTypeDetails::DataView input,
    ::network::mojom::DeviceBoundSessionEventTypeDetailsPtr* output) {
  using UnionType = ::network::mojom::DeviceBoundSessionEventTypeDetails;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kCreation: {
      ::network::mojom::DeviceBoundSessionCreationDetailsPtr result_creation{};
      if (!input.ReadCreation(&result_creation))
        return false;

      *output = UnionType::NewCreation(
          std::move(result_creation));
      break;
    }
    case Tag::kRefresh: {
      ::network::mojom::DeviceBoundSessionRefreshDetailsPtr result_refresh{};
      if (!input.ReadRefresh(&result_refresh))
        return false;

      *output = UnionType::NewRefresh(
          std::move(result_refresh));
      break;
    }
    case Tag::kTermination: {
      ::network::mojom::DeviceBoundSessionTerminationDetailsPtr result_termination{};
      if (!input.ReadTermination(&result_termination))
        return false;

      *output = UnionType::NewTermination(
          std::move(result_termination));
      break;
    }
    case Tag::kChallenge: {
      ::network::mojom::DeviceBoundSessionChallengeDetailsPtr result_challenge{};
      if (!input.ReadChallenge(&result_challenge))
        return false;

      *output = UnionType::NewChallenge(
          std::move(result_challenge));
      break;
    }
    default:

      return false;
  }
  return true;
}

