DeviceBoundSessionManagerAsyncWaiter::DeviceBoundSessionManagerAsyncWaiter(
    DeviceBoundSessionManager* proxy) : proxy_(proxy) {}

DeviceBoundSessionManagerAsyncWaiter::~DeviceBoundSessionManagerAsyncWaiter() = default;


void DeviceBoundSessionManagerAsyncWaiter::GetAllSessions(
    std::vector<DeviceBoundSessionKeyPtr>* out_sessions) {
  base::RunLoop loop;
  proxy_->GetAllSessions(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<DeviceBoundSessionKeyPtr>* out_sessions
,
             std::vector<DeviceBoundSessionKeyPtr> sessions) {*out_sessions = std::move(sessions);
            loop->Quit();
          },
          &loop,
          out_sessions));
  loop.Run();
}

std::vector<DeviceBoundSessionKeyPtr> DeviceBoundSessionManagerAsyncWaiter::GetAllSessions(
    ) {
  std::vector<DeviceBoundSessionKeyPtr> async_wait_result;
  GetAllSessions(&async_wait_result);
  return async_wait_result;
}

void DeviceBoundSessionManagerAsyncWaiter::DeleteAllSessions(
    DeviceBoundSessionDeletionReason reason, std::optional<::base::Time> created_after_time, std::optional<::base::Time> created_before_time, ::network::mojom::ClearDataFilterPtr filter) {
  base::RunLoop loop;
  proxy_->DeleteAllSessions(
      std::move(reason),
      std::move(created_after_time),
      std::move(created_before_time),
      std::move(filter),
      base::BindOnce(
          [](base::RunLoop* loop) {
            loop->Quit();
          },
          &loop));
  loop.Run();
}



void DeviceBoundSessionManagerAsyncWaiter::CreateBoundSessions(
    std::vector<DeviceBoundSessionParamsPtr> params, const std::vector<uint8_t>& wrapped_key, std::vector<::network::mojom::CanonicalCookiePtr> cookies_to_set, ::network::mojom::CookieOptionsPtr cookie_options, std::vector<DeviceBoundSessionError>* out_session_results, std::vector<::network::mojom::CookieInclusionStatusPtr>* out_cookie_results) {
  base::RunLoop loop;
  proxy_->CreateBoundSessions(
      std::move(params),
      std::move(wrapped_key),
      std::move(cookies_to_set),
      std::move(cookie_options),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<DeviceBoundSessionError>* out_session_results
,
             std::vector<::network::mojom::CookieInclusionStatusPtr>* out_cookie_results
,
             const std::vector<DeviceBoundSessionError>& session_results,
             std::vector<::network::mojom::CookieInclusionStatusPtr> cookie_results) {*out_session_results = std::move(session_results);*out_cookie_results = std::move(cookie_results);
            loop->Quit();
          },
          &loop,
          out_session_results,
          out_cookie_results));
  loop.Run();
}






